sys_ux_client_script.required_translations:
[
    {
        "message": "[{0}] generated by Now Assist. Check for accuracy."
    }
]

sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return helpers.translateSync('[{0}] generated by Now Assist. Check for accuracy.', [api.data.record.displayValue]);
}
